mapper.select:
select s.sub_id FROM gc_video v LEFT JOIN gc_subject s ON s.id=v.sub_id WHERE v.id in
#{vid}
GROUP BY s.sub_id

SELECT s.sub_id, v.id, v.video_name, uvp.play_state FROM gc_video AS v LEFT JOIN gc_user_video_play AS uvp ON v.id = uvp.video_id LEFT JOIN gc_subject AS s ON s.id = v.sub_id WHERE uvp.user_id = #{uid}
AND s.sub_id IN
#{subId}
AND uvp.play_state = 1 GROUP BY v.id

		select count(1) from gc_video v
		left join gc_subject sub on sub.id = v.sub_id
		where 


                video_name = #{videoName} 


                video_name_index=#{videoNameIndex}


		and sub.fid = (select fid from gc_subject where id=#{subId})

	        and v.id !=#{id}

select
,sub1.fid as subId0 ,f.thumb_nail_url as thumb_nail_url from gc_video v
left join gc_subject sub1 on v.sub_id =sub1.id left join gc_subject sub0 on sub1.fid =sub0.id where v.video_name_index =#{videoNameIndex} and sub0.name_index = #{subNameIndex} AND sub0.master_id =#{masterId}

SELECT v.video_time as video_long,s.sub_id as sub_id FROM gc_video v left join gc_subject s on s.id=v.sub_id WHERE v.id IN(SELECT id from gc_video where sub_id in (select id from gc_subject where sub_id in
#{subId}
))

SELECT SUM(END_TIME) - SUM(START_TIME) AS SUB_TIME FROM ( SELECT T.VIDEO_ID, T.USER_ID, MAX(T.END_TIME) AS END_TIME, MIN(T.START_TIME) AS START_TIME FROM ( SELECT UVP.VIDEO_ID, UVP.USER_ID, UVPN.END_TIME, UVPN.START_TIME FROM GC_USER_VIDEO_PLAY UVP LEFT JOIN GC_USER_VIDEO_PLAYS_NODE UVPN ON UVPN.VIDEOPLAY_ID = UVP.ID WHERE VIDEO_ID IN
#{videoId}
AND UVPN.END_TIME > UVPN.START_TIME AND USER_ID=#{userId} AND UVPN.START_TIME>= 0 AND UVPN.END_TIME>=0 ) T GROUP BY T.VIDEO_ID, T.USER_ID ) T

select count(g.id) from gc_video g


        AND g.sub_id in

            #{subjectId}

select vp.video_id from gc_user_video_play vp
        left join gc_video v on v.id = vp.video_id
        left join gc_subject s1 on v.sub_id=s1.id
        left join gc_subject s0 on s1.fid=s0.id
where s0.id=#{subId}
and vp.user_id = #{userId}
and vp.master_id = #{masterId}
order by vp.update_time desc limit 1

SELECT sum(uvpn.end_time - uvpn.start_time) as subTime,uvp.user_id as userId FROM gc_user_video_play uvp LEFT JOIN gc_user_video_plays_node uvpn ON uvpn.videoplay_id = uvp.ID WHERE uvpn.end_time > uvpn.start_time AND uvp.user_id in
#{userIdList}
AND uvpn.start_time>= 0 AND uvpn.end_time>=0 and video_id IN
#{videoList}
group by uvp.user_id

select v.id from gc_video v
where v.sub_id in
(select id from gc_subject s1 where s1.fid in

    #{subId}
)

select * from gc_video v
where v.sub_id in
(select id from gc_subject s1 where s1.fid in

    #{subId}
)

SELECT v.*,s.sub_id as subjectSubId FROM gc_video v LEFT JOIN gc_subject s on v.sub_id=s.id
where v.id in
#{videoId}

select count(1) from gc_video v where 1=1
and v.sub_id in (select s.id from gc_subject s where s.sub_id in (select DISTINCT id from gc_subject s where s.master_id=#{masterId} and s.type=#{state} and s.state!=#{state}) UNION ALL (select s.id from gc_subject s where s.type=#{type} and s.state!=#{state} and s.sub_id in (select asso.subject_id from gc_subject_association asso where asso.master_id=#{masterId})) )
and v.sub_id in (select s.id from gc_subject s where s.fid in
#{subId}
)

select s.id as sub_id,sum(v.video_time) as video_long, count(v.id) as video_count from gc_video v left join gc_subject s2 on s2.id = v.sub_id left join gc_subject s on s.id = s2.fid where s.id in
#{subIds}
GROUP BY s.id

SELECT
, s2."fid" AS subId0 ,s2.id as sub_id, u.id as userId from gc_video v left join sys_file f on f.id = v.file_id left join gc_subject s2 on s2.id = v.sub_id left join gc_subject s1 on s1.id = s2.fid left join gc_user u on u.id in
#{userId}
where 1=1 and s1.id = #{subjectId}

SELECT time_bucket, count(DISTINCT video.id) as value FROM sys_file video_file JOIN gc_video video ON video_file.id = video.file_id JOIN gc_user_access user_content_group ON user_content_group.user_id = video_file.upload_uid AND user_content_group.master_id = #{masterId}
AND user_content_group.access_id IN
#{contentGroupId}
RIGHT JOIN generate_series(#{filter.start}, #{filter.end}, concat(#{filter.step}, ' second')::interval) AS time_bucket ON video.create_time >= time_bucket AND video.create_time < time_bucket + concat(#{filter.step}, ' second')::interval GROUP BY time_bucket ORDER BY time_bucket;

SELECT video.id as videoId, count(action.id) AS value
FROM gc_video video
    LEFT JOIN gc_user_video_action action ON video.id = action.content_id
        AND action.type = 1
        AND action.create_time >= #{filter.start}
        AND action.create_time < #{filter.end}

    WHERE video.id IN

        #{videoId}


GROUP BY video.id

SELECT count(1)
FROM gc_user_save_content_follow playlist_follow
         JOIN gc_user_save_content playlist_content ON playlist_content.folder_id = playlist_follow.folder_id AND playlist_content.master_id = #{portalUser.masterId}
WHERE playlist_follow.user_id = #{portalUser.userId}

SELECT
, f.upload_uid as user_id, , channel_content.id AS channel_content_id, ,
(SELECT COUNT(id) FROM gc_video_comment WHERE video_id = v.id) AS comment_num FROM gc_video v JOIN sys_file f ON v.file_id = f.id JOIN pt_channel_content channel_content ON v.id = channel_content.content_id JOIN pt_channel pc ON pc.id = channel_content.channel_id LEFT JOIN sys_file channel_avatar ON channel_avatar.id = pc.channel_avatar_file_id WHERE pc.id = #{channelId} OR pc.fid = #{channelId};
